export function dedupeDocs(docs: Doc[]) {
  const seen = new Set<string>();
  const result: Doc[] = [];

  for (const doc of docs) {
    if (seen.has(doc.id)) continue;
    seen.add(doc.id);
    result.push(doc);
  }

  return result;
}

